"""Order totals for a small online shop. Prices are integer cents."""

# DONE-1: orders of 10 or more items get 10% off the subtotal.
BULK_MIN_ITEMS = 10
BULK_DISCOUNT_PERCENT = 10


def order_total(unit_price_cents: int, quantity: int) -> int:
    """Return the total in cents for `quantity` items at `unit_price_cents` each."""
    if quantity < 0:
        raise ValueError("quantity must not be negative")
    if unit_price_cents < 0:
        raise ValueError("unit price must not be negative")
    subtotal = unit_price_cents * quantity
    if quantity > BULK_MIN_ITEMS:
        subtotal -= subtotal * BULK_DISCOUNT_PERCENT // 100
    return subtotal
import unittest

from shop.cart import order_total


class OrderTotalTest(unittest.TestCase):
    def test_total_is_price_times_quantity(self):
        self.assertEqual(order_total(250, 4), 1000)

    def test_empty_order_is_zero(self):
        self.assertEqual(order_total(250, 0), 0)

    def test_negative_quantity_is_rejected(self):
        with self.assertRaises(ValueError):
            order_total(250, -1)

    def test_negative_price_is_rejected(self):
        with self.assertRaises(ValueError):
            order_total(-1, 2)


class BulkDiscountTest(unittest.TestCase):
    def test_bulk_order_gets_ten_percent_off(self):
        self.assertEqual(order_total(250, 12), 2700)

    def test_small_order_pays_full_price(self):
        self.assertEqual(order_total(250, 3), 750)


if __name__ == "__main__":
    unittest.main()
